+        box-shadow: var(--shadow);
+        padding: clamp(1.5rem, 3vw, 2.25rem);
+      }
+
+      h1 {
+        margin: 0 0 0.5rem;
+        font-size: clamp(1.75rem, 4vw, 2.5rem);
+        line-height: 1.1;
+        letter-spacing: -0.03em;
+      }
+
+      .lede {
+        margin: 0 0 1.75rem;
+        color: var(--muted);
+        max-width: 60ch;
+      }
+
