+        display: grid;
+        gap: 1.25rem;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 0.75rem;
+        padding: 1rem;
+        border: 1px solid var(--border);
+        border-radius: 18px;
+        background: var(--surface-2);
+      }
+
+      .consent-row {
+        display: flex;
+        gap: 0.85rem;
+        align-items: flex-start;
+      }
+
+      input[type="checkbox"] {
+        width: 1.125rem;
+        height: 1.125rem;
+        margin: 0.2rem 0 0;
+        accent-color: var(--primary);
+        flex: none;
+      }
+
+      label {
+        font-weight: 600;
+        color: var(--text);
+      }
+
+      .helper-text {
+        margin: 0;
+        color: var(--muted);
+        font-size: 0.95rem;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+      }
+
+      button {
+        appearance: none;
+        border: 0;
+        border-radius: 999px;
+        padding: 0.9rem 1.25rem;
+        font: inherit;
+        font-weight: 700;
+        color: #fff;
+        background: linear-gradient(180deg, var(--primary), var(--primary-strong));
+        box-shadow: 0 10px 22px rgba(37, 99, 235, 0.25);
+        cursor: pointer;
+      }
+
+      button:hover {
+        filter: brightness(1.02);
+      }
+
+      button:focus-visible,
+      input[type="checkbox"]:focus-visible,
+      .skip-link:focus {
+        outline: 3px solid var(--focus);
+        outline-offset: 3px;
+      }
+
+      .status {
+        min-height: 1.5rem;
+        margin: 0;
+        color: var(--muted);
+        font-weight: 500;
+      }
+
+      .status[data-state="success"] {
+        color: #0f766e;
+      }
+
+      @media (forced-colors: active) {
+        :root {
+          --bg: Canvas;
+          --surface: Canvas;
+          --surface-2: Canvas;
+          --text: CanvasText;
+          --muted: CanvasText;
+          --border: ButtonBorder;
+          --primary: ButtonText;
+          --primary-strong: ButtonText;
+          --focus: Highlight;
+          --shadow: none;
+        }
+
+        .card,
+        .form-field,
+        button,
+        .skip-link {
+          forced-color-adjust: auto;
+        }
+      }
+
+      @media (max-width: 28rem) {
+        .actions {
+          justify-content: stretch;
+        }
+
+        button {
+          width: 100%;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main">Skip to main content</a>
+    <main id="main">
+      <section class="card" aria-labelledby="page-title">
+        <h1 id="page-title">Terms of Use Consent</h1>
+        <p class="lede">Please review and agree before continuing.</p>
+
+        <form id="consent-form" novalidate>
+          <div class="form-field">
+            <div class="consent-row">
+              <input
+                id="terms-consent"
+                name="termsConsent"
+                type="checkbox"
+                required
+                aria-describedby="consent-help"
